class Solution {
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public int countDifferentSubsequenceGCDs(int[] nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);
        boolean[] has = new boolean[maxVal + 1];
        for (int x : nums) has[x] = true;

        int ans = 0;
        for (int g = 1; g <= maxVal; ++g) {
            int currGcd = 0;
            for (int m = g; m <= maxVal; m += g) {
                if (has[m]) {
                    currGcd = gcd(currGcd, m);
                    if (currGcd == g) {
                        ans++;
                        break;
                    }
                }
            }
        }
        return ans;
    }
}

