var countDifferentSubsequenceGCDs = function(nums) {
    let maxVal = 0;
    for (const x of nums) if (x > maxVal) maxVal = x;
    const has = new Uint8Array(maxVal + 1);
    for (const x of nums) has[x] = 1;

    const gcd = (a, b) => {
        while (b) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    let ans = 0;
    for (let g = 1; g <= maxVal; ++g) {
        let currGcd = 0;
        for (let m = g; m <= maxVal; m += g) {
            if (has[m]) {
                currGcd = gcd(currGcd, m);
                if (currGcd === g) {
                    ans++;
                    break;
                }
            }
        }
    }
    return ans;
